    "gu": "પ્રોજેક્ટ અને સ્રોત મિનિટ સેવ કરેલા પ્રોજેક્ટ પરથી છે. સ્ટોરેજમાં તાજેતરમાં કાઢેલા પ્રોજેક્ટની ક્લાઉડ ફાઇલો પણ સામેલ છે. એક્સપોર્ટ, પ્રોસેસિંગ અને ટ્રાન્સક્રિપ્શનના આંકડા આ આવૃત્તિથી બ્રાઉઝર રિપોર્ટ છે; જૂની કે ઑફલાઇન પ્રવૃત્તિ સામેલ નથી. છેલ્લી પ્રવૃત્તિમાં સાઇન ઇન, પ્રોજેક્ટ સેવ અને નોંધાયેલી ઘટનાઓ સામેલ છે. અપડેટ"
