  "Complimentary access bypasses the subscription requirement but keeps project, storage and credit limits. After it expires, normal subscription or trial rules apply. Block cloud writes prevents cloud saves/uploads while keeping existing files; it does not cancel billing or prevent sign-in/local editing.": {
    "hi": "निःशुल्क पहुँच में सदस्यता आवश्यक नहीं, पर प्रोजेक्ट, स्टोरेज और क्रेडिट सीमाएँ लागू रहती हैं। समाप्ति के बाद सामान्य सदस्यता या ट्रायल नियम लागू होते हैं। क्लाउड लेखन रोकने से नए सेव और अपलोड रुकते हैं; मौजूदा फ़ाइलें रहती हैं। बिलिंग, साइन इन और स्थानीय संपादन नहीं रुकते।",
    "gu": "મફત ઍક્સેસમાં સબ્સ્ક્રિપ્શન જરૂરી નથી, પણ પ્રોજેક્ટ, સ્ટોરેજ અને ક્રેડિટ મર્યાદા રહે છે. સમાપ્તિ પછી સામાન્ય સબ્સ્ક્રિપ્શન કે ટ્રાયલના નિયમ લાગુ પડે છે. ક્લાઉડ લેખન રોકવાથી નવા સેવ અને અપલોડ અટકે છે; હાલની ફાઇલો રહે છે. બિલિંગ, સાઇન ઇન અને સ્થાનિક સંપાદન અટકતાં નથી."
  },
