    "hi": "रंग सुधार चालू होने पर पूरे पैक प्रकाश और शुरुआती तत्व जोड़ते हैं। ऑडियो विश्लेषण के बाद ही शांत विराम कटते हैं। मौजूदा क्लिप, संगीत, शब्द और कस्टम शैली रहते हैं। रील टेम्पलेट केवल मूल कैप्शन रूप बदलते हैं। स्टॉक संगीत या बी-रोल नहीं जुड़ता।",
    "gu": "રંગ સુધારો ચાલુ હોય ત્યારે આખા પૅક પ્રકાશ અને શરૂઆતના તત્વો ઉમેરે છે. ઑડિયો વિશ્લેષણ પછી જ શાંત વિરામ કપાય છે. હાલની ક્લિપ, સંગીત, શબ્દ અને કસ્ટમ શૈલી રહે છે. રીલ ટેમ્પ્લેટ માત્ર મૂળ કૅપ્શન દેખાવ બદલે છે. સ્ટોક સંગીત કે બી-રોલ ઉમેરાતું નથી."
