    "gu": "ક્લાઉડ વીડિયો અપલોડના 48 કલાક પછી આપમેળે દૂર થાય છે. તે પહેલાં તૈયાર રીલ ડાઉનલોડ કરો. કૅપ્શન સંપાદન સેવ રહે છે; પછી જોડવા મૂળ વીડિયો રાખો."
