  "What happens after the free trial?": {
    "hi": "मुफ़्त ट्रायल के बाद क्या होता है?",
    "gu": "મફત ટ્રાયલ પછી શું થાય છે?"
  },
  "When billing is enabled, choose a weekly or monthly subscription to continue editing and exporting after your 5-day trial. Your saved project edits remain in your account.": {
    "hi": "बिलिंग चालू होने पर 5 दिन के ट्रायल के बाद संपादन और निर्यात के लिए साप्ताहिक या मासिक सदस्यता चुनें। सेव किए प्रोजेक्ट संपादन खाते में रहते हैं।",
    "gu": "બિલિંગ ચાલુ હોય ત્યારે 5 દિવસની ટ્રાયલ પછી સંપાદન અને એક્સપોર્ટ માટે સાપ્તાહિક કે માસિક સબ્સ્ક્રિપ્શન પસંદ કરો. સેવ કરેલાં પ્રોજેક્ટ સંપાદન ખાતામાં રહે છે."
  },
  "Can I cancel my subscription?": {
    "hi": "क्या सदस्यता रद्द कर सकता हूँ?",
    "gu": "શું સબ્સ્ક્રિપ્શન રદ કરી શકું?"
  },
  "Yes. Cancel renewal from Subscription in the studio. Your already-paid access continues until the paid period ends.": {
    "hi": "हाँ। स्टूडियो में सदस्यता से नवीनीकरण रद्द करें। चुकाई हुई पहुँच अवधि समाप्त होने तक रहती है।",
    "gu": "હા. સ્ટુડિયોમાં સબ્સ્ક્રિપ્શનથી રિન્યૂઅલ રદ કરો. ચૂકવેલી ઍક્સેસ મુદત પૂરી થાય ત્યાં સુધી રહે છે."
  },
  "Are source videos stored forever?": {
    "hi": "क्या स्रोत वीडियो हमेशा रखे जाते हैं?",
    "gu": "શું સ્રોત વીડિયો હંમેશાં રાખવામાં આવે છે?"
  },
  "Cloud videos have a 48-hour retention policy. Keep the original video and download your finished reel. Project and caption edits are retained so you can relink your source later.": {
    "hi": "क्लाउड वीडियो 48 घंटे रखे जाते हैं। मूल वीडियो रखें और तैयार रील डाउनलोड करें। प्रोजेक्ट और कैप्शन संपादन रहते हैं ताकि बाद में स्रोत फिर जोड़ सकें।",
    "gu": "ક્લાઉડ વીડિયો 48 કલાક રાખવામાં આવે છે. મૂળ વીડિયો રાખો અને તૈયાર રીલ ડાઉનલોડ કરો. પ્રોજેક્ટ અને કૅપ્શન સંપાદન રહે છે જેથી પછી સ્રોત ફરી જોડી શકો."
  },
  "Do I need to install an app?": {
    "hi": "क्या ऐप इंस्टॉल करना होगा?",
    "gu": "શું ઍપ ઇન્સ્ટોલ કરવી પડશે?"
  },
  "ReelStudio runs in your browser. Transcription models download on first use; speed and export support depend on your browser and device.": {
    "hi": "ReelStudio ब्राउज़र में चलता है। पहले उपयोग पर ट्रांसक्रिप्शन मॉडल डाउनलोड होते हैं; गति और निर्यात समर्थन ब्राउज़र तथा डिवाइस पर निर्भर हैं।",
    "gu": "ReelStudio બ્રાઉઝરમાં ચાલે છે. પહેલા ઉપયોગે ટ્રાન્સક્રિપ્શન મોડલ ડાઉનલોડ થાય છે; ગતિ અને એક્સપોર્ટ સપોર્ટ બ્રાઉઝર તથા ઉપકરણ પર આધારિત છે."
  },
